@verbatim<script>(function(){var box=document.getElementById('liveSt');if(!box)return;var id=box.dataset.id,fails=0,last=box.dataset.status,okAt=0,busy=false,OPEN=['Shipment','Late Delivery','Return Pending','Partial Delivered'];
function cls(el,slug){if(!el)return;el.className=el.className.replace(/\bs-[\w-]+/g,'').replace(/\s+/g,' ').trim()+' s-'+slug}
function meta(d,bad){var m=document.getElementById('liveStMeta');if(!m)return;var t=d&&d.at?'Updated '+d.at:'Live',sync='';
 if(d&&d.has_courier&&d.synced_min!==null){sync=d.synced_min<1?' \u00b7 courier synced just now':' \u00b7 courier synced '+(d.synced_min<60?d.synced_min+' min':Math.floor(d.synced_min/60)+' h')+' ago'}
 var stale=d&&d.has_courier&&OPEN.indexOf(d.status)>-1&&d.synced_min!==null&&d.synced_min>45;
 if(bad){m.innerHTML='<span style="color:#D97706">&#9679;</span> <b style="color:#B45309">Sync issue</b> \u00b7 last confirmed '+(okAt?new Date(okAt).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}):'earlier')}
 else m.innerHTML='<span style="color:'+(stale?'#D97706':'#16A34A')+'">&#9679;</span> '+(stale?'<b style="color:#B45309">Courier sync issue</b> \u00b7 ':'Live \u00b7 ')+t+sync}
function swap(){fetch(location.href,{credentials:'same-origin',headers:{Accept:'text/html'}}).then(function(r){return r.text()}).then(function(h){var x=new DOMParser().parseFromString(h,'text/html');document.querySelectorAll('[data-live-swap],#soCard').forEach(function(e){var n=e.id&&x.getElementById(e.id);if(n&&n.id!=='liveSt')e.replaceWith(n)});box=document.getElementById('liveSt')||box}).catch(function(){})}
function poll(){if(busy||document.hidden)return;busy=true;fetch('/admin/orders/'+id+'/live',{credentials:'same-origin',headers:{Accept:'application/json'}}).then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(d){fails=0;okAt=Date.now();
 var p=document.getElementById('liveStPill');if(p){p.textContent=d.status;cls(p,d.slug)}var h=document.getElementById('hStPill');if(h){h.textContent=d.status;cls(h,d.slug)}
 var po=document.getElementById('livePO');if(po){var e=function(x){var t=document.createElement('span');t.textContent=x==null?'':x;return t.innerHTML};if(d.outcome||d.raw||d.cflag){po.style.display='';po.innerHTML=(d.outcome?'Pathao Outcome: <b>'+e(d.outcome)+'</b> \u00b7 ':'')+'Pathao status: <b>'+e(d.raw||'\u2014')+'</b>'+(d.cflag?' \u00b7 <b style="color:#B45309">\u26a0 '+e(d.cflag)+'</b> <a href="/admin/courier/status-map" style="font-size:12px">Map it</a>':'')}}
 meta(d,false);if(d.status!==last){last=d.status;swap()}}).catch(function(){fails++;if(fails>=2)meta(null,true)}).then(function(){busy=false})}
setInterval(poll,8000);document.addEventListener('visibilitychange',function(){if(!document.hidden)poll()})})();</script>@endverbatim
